// The outline of the states, generated by `npm run map:outline` and versioned
// (RFC-040 section 5.2): the 27 federative units, within the ceiling, with
// three decimal places, inside Brazil's box, and with where it came from. Here,
// beside the script that writes it, as the other tests of build-time files.

import { readFileSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { LIMIT_BYTES, UNITS } from "./brazil-states.mjs";

const FILE = fileURLToPath(new URL("../src/map/brazil-states.json", import.meta.url));
const SIGLAS = [
  "AC", "AL", "AM", "AP", "BA", "CE", "DF", "ES", "GO", "MA", "MG", "MS", "MT", "PA",
  "PB", "PE", "PI", "PR", "RJ", "RN", "RO", "RR", "RS", "SC", "SE", "SP", "TO",
]; // prettier-ignore

const outline = JSON.parse(readFileSync(FILE, "utf8"));

function* positions(coordinates) {
  if (typeof coordinates[0] === "number") {
    yield coordinates;
    return;
  }
  for (const part of coordinates) {
    yield* positions(part);
  }
}

describe("the outline of the states", () => {
  it("has the 27 federative units, one feature each, and polygons", () => {
    expect(UNITS).toBe(27);
    expect(outline.type).toBe("FeatureCollection");
    expect(outline.features.map((feature) => feature.properties.sigla).sort()).toEqual(
      SIGLAS,
    );
    for (const feature of outline.features) {
      expect(["Polygon", "MultiPolygon"]).toContain(feature.geometry.type);
      expect(feature.properties.name.length).toBeGreaterThan(0);
    }
  });

  it("is within the ceiling of 200 KB", () => {
    expect(LIMIT_BYTES).toBe(200 * 1024);
    expect(statSync(FILE).size).toBeLessThanOrEqual(LIMIT_BYTES);
  });

  it("has three decimal places, and stays inside Brazil's box", () => {
    let count = 0;
    for (const feature of outline.features) {
      for (const [lon, lat] of positions(feature.geometry.coordinates)) {
        count += 1;
        expect(Math.round(lon * 1_000) / 1_000).toBe(lon);
        expect(Math.round(lat * 1_000) / 1_000).toBe(lat);
        expect(lon).toBeGreaterThanOrEqual(-74.1);
        expect(lon).toBeLessThanOrEqual(-28.8);
        expect(lat).toBeGreaterThanOrEqual(-33.8);
        expect(lat).toBeLessThanOrEqual(5.3);
      }
    }
    expect(count).toBeGreaterThan(1_000);
  });

  it("says where it came from: the URL, the version, and the hash", () => {
    expect(outline.source.url).toBe(
      "https://naciscdn.org/naturalearth/10m/cultural/ne_10m_admin_1_states_provinces.zip",
    );
    expect(outline.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(outline.source.version).toBe("5.1.1");
    expect(String(outline.source.license)).toMatch(/^Public domain/);
  });
});
